test_cmd:
mkdir -p "$ENV/home" "$ENV/tmp" "$ENV/pycache" && HOME="$ENV/home" TMPDIR="$ENV/tmp" PYTHONPYCACHEPREFIX="$ENV/pycache" PYTHONPATH=. OPENAI_API_KEY=sk-dummy ANTHROPIC_API_KEY=sk-ant-dummy DEEPSEEK_API_KEY=dummy OPENROUTER_API_KEY=dummy GEMINI_API_KEY=dummy LITELLM_LOCAL_MODEL_COST_MAP=True WANDB_MODE=disabled HF_HUB_OFFLINE=1 TRANSFORMERS_OFFLINE=1 MPLBACKEND=Agg $PY -c 'import sys,time,compileall,importlib,traceback
t=time.time(); ok=0; bad=0
for d in ["ai_scientist","launch_scientist.py","experimental","review_iclr_bench"]:
    r = compileall.compile_file(d,quiet=1) if d.endswith(".py") else compileall.compile_dir(d,quiet=1)
    if r: ok+=1; print("PASSED compileall", d)
    else: bad+=1; print("FAILED compileall", d)
for m in ["ai_scientist.llm","ai_scientist.generate_ideas","ai_scientist.perform_experiments","ai_scientist.perform_review","ai_scientist.perform_writeup","launch_scientist"]:
    try:
        importlib.import_module(m); ok+=1; print("PASSED import", m)
    except BaseException:
        bad+=1; print("FAILED import", m); traceback.print_exc()
dt=time.time()-t
print((str(bad)+" failed, " if bad else "")+str(ok)+" passed in "+format(dt,".2f")+"s")
sys.exit(1 if bad else 0)'
